    "Ceritakan kronologi kejadian yang dialami/dilihat bila berkenan (apa yang dilakukan/diucapkan pelaku).  ": "Can a nigga borrow a fry?\n\nWhat I don't understand is that if it's so offensive to them then why do they say it over and over again? He says it every morning. He calls me nigga, he calls the other kids nigga, he calls himself nigga. All the time. Nigga this, nigga that, nigga PLEASE. Bitch nigga. Nigga have you lost your mind? Nigga check that hoe. Nigga, you bullshittin. Break yourself, nigga.\n\nHe says it so much I don't even notice it anymore. Last week during lunch, Riley says to a classmate, \"Can a nigga borrow a French fry?\" My first thought wasn't \"Oh my God he said the word, t-the n-word!\" It was \"How is a nigga gonna borrow a fry? Nigga, is you gonna give it back?\" I'm telling you my inside voice didn't talk like that before he got in my class",
