    "Perkiraan waktu (Tanggal, hari, dan jam)": "“Sexual desire is preoccupied with youth, and the progressive influx of ever-younger girls onto the field of seduction was simply a return to the norm; a restoration of the true nature of desire, comparable to the return of stock prices to their true value after a run on the exchange. Nonetheless, women who turned twenty in the late sixties found themselves in a difficult position when they hit forty. Most of them were divorced and could no longer count on the conjugal bond — whether warm or abject — whose decline they had served to hasten. As members of a generation who — more than any before — had proclaimed the superioirity of youth over age, they could hardly claim to be surprised when they, in turn, were despised by succeeding generations. As their flesh began to age, the cult of the body, which they had done so much to promote, simply filled them with an intensifying disgust with their own bodies — a disgust they could see mirrored in the gaze of others.” – The Elementary Particles, Michel Houllebecq"
